package delivery;
public record Route(String id, Location origin, Location destination, double distanceKm, int estimatedMinutes, double cost, double carbonEmission, boolean available, int trafficMinutes, double extraFee) { public Route { if(id == null || id.isBlank() || origin == null || destination == null || !Double.isFinite(distanceKm) || distanceKm < 0 || estimatedMinutes <= 0 || !Double.isFinite(cost) || cost < 0 || !Double.isFinite(carbonEmission) || carbonEmission < 0 || trafficMinutes < 0 || !Double.isFinite(extraFee) || extraFee < 0) throw new IllegalArgumentException("Invalid route"); } }
